SELECT r.role_no AS roleNo, r.role_name AS roleName, r.user_no AS userNo, r.role_level AS roleLevel, u.user_name AS userName, u.email AS email, p.position_name AS position, k.rank_name AS rank FROM ROLE r JOIN USERS u ON r.user_no = u.user_no LEFT JOIN TITLE t ON u.user_no = t.user_no LEFT JOIN POSITION p ON t.position_no = p.position_no LEFT JOIN RANK k ON t.rank_no = k.rank_no WHERE r.company_no = #{companyNo} AND r.role_level = #{roleLevel}
AND r.role_name = #{roleName}
AND r.user_no IS NOT NULL

